80	        int raw_x = readincr(px_xyz_in);
81	        int raw_y = readincr(px_xyz_in);
82	        int raw_z = readincr(px_xyz_in);
83	
84	        x_trgt_pxls[px_idx] = *reinterpret_cast<float*>(&raw_x);
85	        y_trgt_pxls[px_idx] = *reinterpret_cast<float*>(&raw_y);
86	        z_trgt_pxls[px_idx] = *reinterpret_cast<float*>(&raw_z);
87	    }
88	    
89	    // Initialize radar params
90	    float ph_corr_coef = (4*PI*MIN_FREQ)/C;
91	
92	    // Initialize range and azimuth grid
93	    int half_size = RC_SAMPLES/2;
94	    
95	    // Extract antenna position and range to scene center from slow time data
96	    auto st_in_vec_iter = aie::begin_vector<BC_ELEMENTS>(slowtime_in);
97	    auto st_in_vec = *st_in_vec_iter++;
98	    float x_ant = st_in_vec[0];
99	    float y_ant = st_in_vec[1];
100	    float z_ant = st_in_vec[2];
101	    float r0 = st_in_vec[3];
102	    
103	    // Ranged compressed data in time domain (compressed range lines)
104	    auto rc_in_iter = aie::begin(rc_in);
105	
106	    // Declare X, Y, and Z target pixel float vectors
107	    aie::vector<float,16> x_pxls_vec;
108	    aie::vector<float,16> y_pxls_vec;
109	    aie::vector<float,16> z_pxls_vec;
110	    
111	    for(int px_seg_idx=0; px_seg_idx < SAMPLES/16; px_seg_idx++) chess_prepare_for_pipelining {
112	
113	        // Extract X, Y and Z target pixel buffers into their respective pixel vectors
114	        x_pxls_vec.load(x_trgt_pxls + px_seg_idx*16);
115	        y_pxls_vec.load(y_trgt_pxls + px_seg_idx*16);
116	        z_pxls_vec.load(z_trgt_pxls + px_seg_idx*16);
117	
118	        /**** CALCULATE DIFFERENTIAL RANGE FOR PIXEL SEGMENTS ****/
119	        // Calculate this on host to corr pixels to rc...calc
120	        // boundaries/extremes instead of the whole thing on host
121	        auto x_vec = aie::sub(x_ant, x_pxls_vec);
122	        auto x_diff_sq_acc = aie::mul_square(x_vec);
123	
124	        auto y_vec = aie::sub(y_ant, y_pxls_vec);
125	        auto y_diff_sq_acc = aie::mul_square(y_vec);
126	
127	        auto z_vec = aie::sub(z_ant, z_pxls_vec);
128	        auto z_diff_sq_acc = aie::mul_square(z_vec);
129	
130	        auto xy_add_acc = aie::add(x_diff_sq_acc, y_diff_sq_acc.to_vector<float>(0));
131	        auto xyz_add_acc = aie::add(xy_add_acc, z_diff_sq_acc.to_vector<float>(0));
132	
133	        auto xyz_sqrt_acc = aie::sqrt(xyz_add_acc);
134	
135	        auto differ_range_vec = aie::sub(xyz_sqrt_acc, r0).to_vector<float>(0);
136	
137	        // Calculate the approximate index for differ_range_vec in the equally
138	        // spaced range grid
139	        auto px_idx_acc = aie::mul(INV_RANGE_RES, differ_range_vec);
140	
141	        // Shift indices to align with proper range compressed samples
142	        px_idx_acc = aie::add(px_idx_acc, (float)(half_size));
143	
144	        // Round to nearest whole number
145	        auto low_idx_float_vec = aie::sub(px_idx_acc, 0.5f).to_vector<float>(0);
146	        auto low_idx_int_vec = aie::to_fixed<int32>(low_idx_float_vec);
147	        auto high_idx_int_vec = aie::add(low_idx_int_vec, 1);
148	
149	        //**** CALCULATE PHASE CORRECTION FOR IMAGE ****//
150	        auto ph_corr_angle_vec = aie::mul(ph_corr_coef, differ_range_vec).to_vector<float>(0);
151	
152	        // Figure out the number of times 2*PI goes into ph_corr_angle_vec.
153	        // Floor round to neg infinity by casting to int32, then back to float
154	        // for later operations
155	        auto num_pi_wrapped_acc = aie::mul(INV_TWO_PI, ph_corr_angle_vec);
156	        auto num_pi_wrapped_floor_vec = aie::sub(num_pi_wrapped_acc, 0.5f).to_vector<float>(0);
157	        auto num_pi_wrapped_int_vec = aie::to_fixed<int32>(num_pi_wrapped_floor_vec); // Round to nearest whole number
158	        num_pi_wrapped_floor_vec = aie::to_float(num_pi_wrapped_int_vec);
159	
160	        // Scale down ph_corr_angle to be within valid domain for sin/cos
161	        // operation (must be between -PI to PI; modulus doesn't exist)
162	        auto scale_down_angle_acc = aie::negmul(TWO_PI, num_pi_wrapped_floor_vec);
163	        scale_down_angle_acc = aie::sub(scale_down_angle_acc, PI);
164	        ph_corr_angle_vec = aie::add(scale_down_angle_acc, ph_corr_angle_vec).to_vector<float>(0);
165	
166	        // Calculate the sin and cos of ph_corr_angle and store as a cfloat
167	        // (cos in the real part, sin in the imaginary)
168	        auto ph_corr_vec = aie::sincos_complex(ph_corr_angle_vec);
169	        ph_corr_vec = aie::neg(ph_corr_vec);
170	        auto ph_corr_real = aie::real(ph_corr_vec);
171	        auto ph_corr_imag = aie::imag(ph_corr_vec);
172	        
173	        // Fractional part for interpolation
174	        low_idx_float_vec = aie::to_float(low_idx_int_vec);
175	        auto px_delta_idx_vec = aie::sub(px_idx_acc, low_idx_float_vec).to_vector<float>(0);
176	        
177	        cfloat rc_delta;
178	        for(int px_idx=0; px_idx<16; px_idx++) chess_prepare_for_pipelining {
179	            rc_delta = rc_in_iter[high_idx_int_vec.get(px_idx)] - rc_in_iter[low_idx_int_vec.get(px_idx)];
180	            auto px_rc_delta = rc_delta*(float)(px_delta_idx_vec.get(px_idx));
181	            auto interp = px_rc_delta+rc_in_iter[low_idx_int_vec.get(px_idx)];
182	
183	            auto img = interp*ph_corr_vec.get(px_idx);
184	            m_img[(px_seg_idx*16) + px_idx] += img;
185	        }
186	    }
187	
188	    if (rtp_dump_img_in) {
189	        
190	        // Create iterator for m_img buffer
191	        auto img_iter = aie::begin(m_img);
192	
193	        // Get first element from m_img buffer
194	        cfloat img_elem = *img_iter++;
195	
196	        // Construct and place uint32 header on img_out stream
197	        writeHeader(img_out, 0, getPacketid(img_out, 0));
198	
199	        // Add additional metadata indicating kernel instantiation number
200	        writeincr(img_out, m_id, false);
201	    
202	        // Add two uint32 padding since bus width is 128 bit 
203	        writeincr(img_out, 0, false);
204	        writeincr(img_out, 0, false);
205	
206	        for(int i=0; i<SAMPLES-1; i++) chess_prepare_for_pipelining {
207	            writeincr(img_out, img_elem.real, false);
208	            writeincr(img_out, img_elem.imag, false);
209	            img_elem = *img_iter++;
210	        }
211	        writeincr(img_out, img_elem.real, false);
212	        writeincr(img_out, img_elem.imag, true);
213	    }
214	}
